import React, { useState, useEffect, useRef } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, LineElement, PointElement,
  LinearScale, CategoryScale, Filler, Tooltip, Legend
} from 'chart.js';
import { getGraphConfidence, getGraphTimeline } from '../services/api';

ChartJS.register(
  LineElement, PointElement,
  LinearScale, CategoryScale,
  Filler, Tooltip, Legend
);

const CLASS_COLORS = {
  Normal:       '#22c55e',
  Phone:        '#60a5fa',
  Medical_Mask: '#34d399',
  Fire:         '#fb923c',
  Smoke:        '#94a3b8',
  Gun:          '#f87171',
  Knife:        '#facc15',
  Falling:      '#a78bfa',
  Violence:     '#f43f5e',
  Theft_Mask:   '#fbbf24'
};

const THREAT_CLASSES = [
  'Fire', 'Smoke', 'Gun', 'Knife',
  'Falling', 'Violence', 'Theft_Mask'
];

const gridColor = '#1e2d47';
const tickStyle = { color: '#64748b', font: { size: 9 } };

const TIME_OPTIONS = [
  { label: '1 Hour',  value: 1  },
  { label: '5 Hours', value: 5  },
  { label: '12 Hours',value: 12 },
  { label: '1 Day',   value: 24 },
];

export default function ChartsRow() {
  const [confidence,   setConfidence]   = useState({});
  const [timeline,     setTimeline]     = useState({ labels: [], counts: [] });
  const [confHours,    setConfHours]    = useState(1);
  const [timeHours,    setTimeHours]    = useState(1);
  const [confClass,    setConfClass]    = useState('all');
  const intervalRef = useRef(null);

  const loadData = async () => {
    try {
      const [confRes, timeRes] = await Promise.all([
        getGraphConfidence(confHours),
        getGraphTimeline(timeHours)
      ]);
      setConfidence(confRes.data.classes || {});
      setTimeline({
        labels: timeRes.data.labels || [],
        counts: timeRes.data.counts || []
      });
    } catch (err) {
      console.warn('[ChartsRow] Load failed:', err);
    }
  };

  // Reload when hours change
  useEffect(() => {
    loadData();
  }, [confHours, timeHours]);

  // Auto refresh every 3 seconds
  useEffect(() => {
    intervalRef.current = setInterval(loadData, 3000);
    return () => clearInterval(intervalRef.current);
  }, [confHours, timeHours]);

  // ── Confidence chart data ────────────────────────────────────
  // Filter by selected class
  const displayClasses = confClass === 'all'
    ? Object.keys(CLASS_COLORS)
    : [confClass];

  // Collect all unique time labels across classes
  const allTimeLabels = [];
  Object.values(confidence).forEach(points => {
    points.forEach(p => {
      if (!allTimeLabels.includes(p.time_label)) {
        allTimeLabels.push(p.time_label);
      }
    });
  });
  allTimeLabels.sort();

  // If no real data yet — show last 20 time points
  const confLabels = allTimeLabels.length > 0
    ? allTimeLabels.slice(-30)
    : Array.from({ length: 10 }, (_, i) => `${i + 1}`);

  const confDatasets = displayClasses
    .filter(cls => {
      // Show class if it has data OR if showing all
      const hasData = confidence[cls] && confidence[cls].length > 0;
      if (confClass !== 'all') return true;
      return hasData;
    })
    .map(cls => {
      const points = confidence[cls] || [];
      const color  = CLASS_COLORS[cls];

      // Map points to labels
      const dataMap = {};
      points.forEach(p => { dataMap[p.time_label] = p.confidence; });

      const data = confLabels.map(lbl => dataMap[lbl] ?? null);

      return {
        label:       cls,
        data,
        borderColor: color,
        borderWidth: THREAT_CLASSES.includes(cls) ? 2 : 1.5,
        pointRadius: points.length < 20 ? 3 : 1,
        pointBackgroundColor: color,
        fill:        false,
        tension:     0.4,
        spanGaps:    true
      };
    });

  const confChartData = {
    labels:   confLabels,
    datasets: confDatasets
  };

  // ── Timeline chart data ──────────────────────────────────────
  const timelineChartData = {
    labels:   timeline.labels,
    datasets: [{
      label:           'Detections',
      data:            timeline.counts,
      borderColor:     '#3b82f6',
      borderWidth:     2,
      fill:            true,
      backgroundColor: 'rgba(59,130,246,.15)',
      pointRadius:     timeline.labels.length < 20 ? 3 : 0,
      pointBackgroundColor: '#3b82f6',
      tension:         0.4
    }]
  };

  // ── Chart options ────────────────────────────────────────────
  const confOpts = {
    animation:  false,
    responsive: true,
    plugins: {
      legend: {
        display:  true,
        position: 'bottom',
        labels: {
          color:    '#64748b',
          font:     { size: 8 },
          boxWidth: 8,
          padding:  6
        }
      },
      tooltip: {
        callbacks: {
          label: ctx =>
            `${ctx.dataset.label}: ${ctx.parsed.y != null
              ? ctx.parsed.y.toFixed(2) : 'N/A'}`
        }
      }
    },
    scales: {
      x: {
        ticks: {
          color:         '#64748b',
          font:          { size: 8 },
          maxTicksLimit: 8,
          maxRotation:   0
        },
        grid: { color: gridColor }
      },
      y: {
        min:   0,
        max:   1,
        ticks: { ...tickStyle, stepSize: .25 },
        grid:  { color: gridColor }
      }
    }
  };

  const timeOpts = {
    animation:  false,
    responsive: true,
    plugins: {
      legend: { display: false },
      tooltip: {
        callbacks: {
          label: ctx => `Detections: ${ctx.parsed.y}`
        }
      }
    },
    scales: {
      x: {
        ticks: {
          color:         '#64748b',
          font:          { size: 8 },
          maxTicksLimit: 8,
          maxRotation:   0
        },
        grid: { color: gridColor }
      },
      y: {
        min:   0,
        ticks: { ...tickStyle },
        grid:  { color: gridColor }
      }
    }
  };

  // ── Select style ─────────────────────────────────────────────
  const selStyle = {
    background:   '#1a2340',
    border:       '1px solid #253550',
    color:        '#94a3b8',
    fontSize:     10,
    padding:      '3px 6px',
    borderRadius: 4,
    cursor:       'pointer',
    outline:      'none'
  };

  return (
    <div style={{
      display:             'grid',
      gridTemplateColumns: '1fr 1fr',
      gap:                 8,
      marginBottom:        10
    }}>

      {/* ── Confidence Score Graph ──────────────────────────── */}
      <div style={{
        background:   '#151d2e',
        border:       '1px solid #1e2d47',
        borderRadius: 8,
        padding:      10
      }}>
        <div style={{
          display:        'flex',
          justifyContent: 'space-between',
          alignItems:     'center',
          marginBottom:   6
        }}>
          <span style={{
            fontSize:      11, fontWeight: 700,
            color:         '#94a3b8',
            textTransform: 'uppercase',
            letterSpacing: '.5px'
          }}>
            Confidence Score Graph
          </span>
          <div style={{ display: 'flex', gap: 4 }}>
            {/* Class filter */}
            <select
              style={selStyle}
              value={confClass}
              onChange={e => setConfClass(e.target.value)}
            >
              <option value="all">All Classes</option>
              {Object.keys(CLASS_COLORS).map(cls => (
                <option key={cls} value={cls}>
                  {cls.replace('_', ' ')}
                </option>
              ))}
            </select>

            {/* Time filter */}
            <select
              style={selStyle}
              value={confHours}
              onChange={e => setConfHours(Number(e.target.value))}
            >
              {TIME_OPTIONS.map(opt => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>
        </div>

        {confDatasets.length === 0 ? (
          <div style={{
            height:         160,
            display:        'flex',
            flexDirection:  'column',
            alignItems:     'center',
            justifyContent: 'center',
            color:          '#64748b',
            fontSize:       11,
            gap:            6
          }}>
            <span style={{ fontSize: 24 }}>📊</span>
            No detections in selected time range
          </div>
        ) : (
          <Line data={confChartData} options={confOpts} />
        )}
      </div>

      {/* ── Detections Over Time ────────────────────────────── */}
      <div style={{
        background:   '#151d2e',
        border:       '1px solid #1e2d47',
        borderRadius: 8,
        padding:      10
      }}>
        <div style={{
          display:        'flex',
          justifyContent: 'space-between',
          alignItems:     'center',
          marginBottom:   6
        }}>
          <span style={{
            fontSize:      11, fontWeight: 700,
            color:         '#94a3b8',
            textTransform: 'uppercase',
            letterSpacing: '.5px'
          }}>
            Detections Over Time
          </span>
          <div style={{ display: 'flex', gap: 4 }}>
            {/* Time filter */}
            <select
              style={selStyle}
              value={timeHours}
              onChange={e => setTimeHours(Number(e.target.value))}
            >
              {TIME_OPTIONS.map(opt => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>
        </div>

        <Line data={timelineChartData} options={timeOpts} />
      </div>

    </div>
  );
}
